const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// A history restore can otherwise show the account state from before sign-in/out.
window.addEventListener('pageshow',event=>{if(event.persisted)window.location.reload()});
document.querySelectorAll('.account-avatar img').forEach(img=>{img.addEventListener('error',()=>img.remove());if(img.complete&&img.naturalWidth===0)img.remove()});
const icon=name=>'<svg class="icon" aria-hidden="true"><use href="#i-'+name+'"/></svg>';
// Only the requested ecosystem strip loops; it pauses offscreen, on hover/focus, or by choice.
const ribbon=document.querySelector('.agent-ribbon'),ribbonButton=document.querySelector('.ribbon-control');
let ribbonPaused=false,ribbonVisible=false;
const motionPreference=matchMedia('(prefers-reduced-motion: reduce)');
function updateRibbon(){ribbon.classList.toggle('running',ribbonVisible&&!ribbonPaused&&!document.hidden&&!motionPreference.matches)}
new IntersectionObserver(entries=>{ribbonVisible=entries[0].isIntersecting;updateRibbon()},{threshold:.1}).observe(ribbon);
ribbonButton.addEventListener('click',()=>{ribbonPaused=!ribbonPaused;ribbonButton.setAttribute('aria-pressed',String(ribbonPaused));ribbonButton.setAttribute('aria-label',ribbonPaused?'Resume agent logo animation':'Pause agent logo animation');ribbonButton.innerHTML=icon(ribbonPaused?'play':'pause');updateRibbon()});
document.addEventListener('visibilitychange',updateRibbon);motionPreference.addEventListener('change',updateRibbon);


const workflowCases=[{"name": "Research a market", "conversation": "Market research", "result": "A market decision you can act on.", "steps": [{"agent": "Codex", "prompt": "I\u2019m building Velora, an AI video platform for small brands. Research Runway, Luma and Adobe Firefly. Where could a new product still win?", "status": ["Searching official product pages", "Comparing workflows and saving sources"], "output": "<h3>A new generator alone won\u2019t be enough.</h3><p>All three already offer broad creative workflows and multiple models. \u201cMore models in one place\u201d is a crowded proposition.</p><table><thead><tr><th>Platform</th><th>What the product already covers</th></tr></thead><tbody><tr><td>Runway</td><td>Generation, editing and custom creative workflows.</td></tr><tr><td>Luma</td><td>Creative agents, shared brand context and connected workflows.</td></tr><tr><td>Adobe Firefly</td><td>Multi-model video generation, editing and export.</td></tr></tbody></table><p><strong>A narrower opening to test:</strong> turn a small brand\u2019s product photos into a repeatable set of social ad variations. Compete on getting usable variants approved, not on generating one impressive clip.</p><p><span class=\"source-links\">Sources: <a href=\"https://runway.com/product\" target=\"_blank\" rel=\"noopener\">Runway</a> \u00b7 <a href=\"https://lumalabs.ai/app\" target=\"_blank\" rel=\"noopener\">Luma</a> \u00b7 <a href=\"https://www.adobe.com/products/firefly/features/ai-video-generator.html\" target=\"_blank\" rel=\"noopener\">Adobe Firefly</a></span></p>", "apps": ["Browser", "Project files"], "title": "Find the market opening", "duration": 26, "key": "0-0"}, {"agent": "Claude", "prompt": "Based on that research, should we focus on small brands or filmmakers? Pick one, define our first workflow, and challenge the biggest assumption.", "status": ["Reading the research and source notes", "Comparing the two customer workflows"], "output": "<h3>Start with small brands. Prove repeat use.</h3><p>Choose a lean marketing team that needs fresh product ads every week. Its job is measurable: make several usable variations from existing product assets, with less back-and-forth.</p><ul><li><strong>The first workflow:</strong> upload a product photo \u2192 write a short brief \u2192 generate three variations \u2192 compare and approve \u2192 export for social.</li><li><strong>Leave out:</strong> a full timeline editor, long-form filmmaking and an unlimited model catalog.</li><li><strong>The risky assumption:</strong> teams will trust generated footage to preserve their product. A beautiful clip that changes the packaging is unusable.</li></ul><p>Before building broadly, run five assisted projects using real brand assets. Look for a second project request, not just a positive reaction.</p>", "apps": ["Research notes", "Project files"], "title": "Choose the first customer", "duration": 26, "key": "0-1"}, {"agent": "Claude", "prompt": "Turn this into a concise PDF for my cofounder: competitor comparison, our product decision, MVP scope and a two-week validation plan. Keep assumptions separate from findings.", "status": ["Organizing findings and recommendations", "Formatting the PDF and checking source links"], "output": "<h3>The decision is ready to share.</h3><p>The report keeps observed competitor capabilities separate from our proposed positioning. It recommends a focused product-ad workflow and spells out what would make us change direction.</p><ul><li><strong>Market:</strong> three established platforms, their workflows and the implications for Velora.</li><li><strong>Product:</strong> one target customer, a five-step MVP and explicit exclusions.</li><li><strong>Validation:</strong> five assisted projects, product-fidelity checks and a repeat-use decision after two weeks.</li></ul><button class=\"output-file\" data-artifact=\"report\"><svg width=\"24\" height=\"28\" viewBox=\"0 0 24 28\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\"><path d=\"M4 1h10l6 6v20H4zM14 1v7h6M8 14h8M8 19h6\"/></svg><span><strong>Velora \u2014 Market & product brief.pdf</strong><small>5 pages \u00b7 Sources, decision and validation plan</small></span><span class=\"file-open\">Open</span></button><p>I\u2019ll use this same brief for the product design and the creator launch plan.</p>", "apps": ["Project files", "PDF export"], "title": "Make the PDF", "duration": 26, "key": "0-2"}]}, {"name": "Build an app", "conversation": "Build Velora", "result": "From the research to a working product prototype.", "steps": [{"agent": "Claude", "prompt": "Use the referenced market research to write a build-ready MVP brief for Velora. Carry over the customer decision, product scope and validation criteria.", "status": ["Reading Velora \u2014 Market & product brief.pdf", "Defining the user flow and acceptance criteria"], "output": "<h3>Build one excellent \u201cbrief to variations\u201d flow.</h3><p>Keep the product image, brief and output together. Start with one generation provider so we can validate the workflow before broadening the model catalog.</p><table><thead><tr><th>Screen</th><th>Acceptance criterion</th></tr></thead><tbody><tr><td>Create</td><td>A product image and brief are required; duration and format are explicit.</td></tr><tr><td>Compare</td><td>Each variation keeps its own prompt, job state and feedback.</td></tr><tr><td>Review</td><td>Approve one direction, keep alternatives, export the selected result.</td></tr></tbody></table><p><strong>Handle failure:</strong> show which job failed, keep the inputs and allow a retry. Don\u2019t erase a successful variation when another fails.</p><p><strong>First design task:</strong> a calm workspace with the brief on the left and a contact sheet of variations on the right.</p>", "apps": ["Market PDF", "Project files"], "title": "Define the product", "duration": 26, "key": "1-0"}, {"agent": "Kimi", "prompt": "Design the workspace from that brief. Make it feel like a creative tool, not an admin dashboard. Show the input, generation state and comparison view in one design.", "status": ["Reading the product brief and acceptance criteria", "Designing the creation and comparison states"], "output": "<h3>The brief stays beside the work.</h3><p>I\u2019ve organized the workspace around a single campaign. The input stays visible while variations render; finished clips appear in a contact sheet without moving the controls.</p><ul><li><strong>Inputs:</strong> product reference, scene brief, aspect ratio and clip length.</li><li><strong>During generation:</strong> each variation has its own progress and state.</li><li><strong>After generation:</strong> review a direction, save it to the campaign and compare the remaining versions.</li></ul><button class=\"output-file\" data-artifact=\"design\"><svg width=\"24\" height=\"28\" viewBox=\"0 0 24 28\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\"><path d=\"M4 1h10l6 6v20H4zM14 1v7h6M8 14h8M8 19h6\"/></svg><span><strong>Velora workspace \u2014 design preview</strong><small>Create, generating and compare states</small></span><span class=\"file-open\">Open</span></button><p>The sample campaign is a short product film for a skincare brand. DeepSeek can implement this layout directly.</p>", "apps": ["Product brief", "Browser preview"], "title": "Design the workspace", "duration": 26, "key": "1-1"}, {"agent": "DeepSeek", "prompt": "Implement Kimi\u2019s design as a working prototype. Keep the layout. Make the inputs, generation queue, comparison and save action work. Use local sample results for now.", "status": ["Reading the design and product brief", "Building the form, job states and comparison view"], "output": "<h3>The product flow is ready to try.</h3><p>The prototype keeps Kimi\u2019s layout and supports the complete interaction: edit a brief, choose a format, generate variations, review a direction and save it to the campaign.</p><ul><li>Empty briefs get an inline error; submitted values stay attached to each result.</li><li>Generation moves through queued, rendering and ready states.</li><li>Saving a direction updates the campaign without resetting the other variations.</li></ul><button class=\"output-file\" data-artifact=\"app\"><svg width=\"24\" height=\"28\" viewBox=\"0 0 24 28\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\"><path d=\"M4 1h10l6 6v20H4zM14 1v7h6M8 14h8M8 19h6\"/></svg><span><strong>Velora Studio \u2014 interactive prototype.html</strong><small>Open locally \u00b7 No account or installation needed</small></span><span class=\"file-open\">Open</span></button><p>Generation uses local sample scenes in this prototype. The next engineering step is connecting a real video provider.</p>", "apps": ["Design preview", "Project files"], "title": "Build the prototype", "duration": 26, "key": "1-2"}]}, {"name": "Run your socials", "conversation": "Creator launch", "result": "A qualified shortlist, a pilot and personal outreach.", "steps": [{"agent": "Grok Bot", "prompt": "Use our referenced market research and product build conversations to find X creators who could demo Velora. Focus on hands-on AI video workflows for small brands.", "status": ["Searching X for product-video workflows", "Reviewing demo formats and audience questions"], "output": "<h3>Prioritize people who show the process.</h3><p>For this launch, a smaller creator who demonstrates product-image workflows is a better starting point than a broad AI news account. I\u2019ve organized the sample shortlist by the demonstration we\u2019d ask each person to make.</p><table><thead><tr><th>Creator / X</th><th>Relevant angle</th><th>What to check next</th></tr></thead><tbody><tr><td>Maya Motion Studio</td><td>Product-image-to-video breakdowns</td><td>Can the product stay recognizable across takes?</td></tr><tr><td>Cutroom Notes</td><td>Side-by-side creative workflow tests</td><td>Would they compare multiple ad variations?</td></tr><tr><td>Small Brand Lab</td><td>Practical creative tests for shops</td><td>Does their audience actually make ads?</td></tr></tbody></table><p>Next, cross-check long-form work on YouTube before ranking anyone. A useful post alone is not enough to establish fit.</p>", "apps": ["X", "Project files"], "title": "Discover the right creators", "duration": 26, "key": "2-0"}, {"agent": "Codex", "prompt": "Cross-check that shortlist on YouTube and add one tutorial-first creator. Judge the quality of the demo and audience fit. Tell me who to prioritize and what we still need to verify.", "status": ["Reviewing YouTube tutorial formats", "Matching creator evidence to the product brief"], "output": "<h3>Two leads for the first pilot. Two to qualify.</h3><table><thead><tr><th>Creator</th><th>Why they fit</th><th>Next step</th></tr></thead><tbody><tr><td>Maya Motion Studio \u00b7 X + YouTube</td><td>A full product-photo-to-video walkthrough fits our core use case.</td><td>Request a product-fidelity test.</td></tr><tr><td>Prompt to Picture \u00b7 YouTube</td><td>A tutorial can show the brief, variations and final choice.</td><td>Confirm interest in a hands-on pilot.</td></tr><tr><td>Cutroom Notes \u00b7 X + YouTube</td><td>Comparison format could explain why iteration matters.</td><td>Verify small-brand audience fit.</td></tr><tr><td>Small Brand Lab \u00b7 X</td><td>Relevant audience; video teaching depth is unclear.</td><td>Ask for a previous workflow demo.</td></tr></tbody></table><p><strong>Recommendation:</strong> lead with Maya and Prompt to Picture. Before outreach, verify current public profiles, audience relevance and commercial terms. No follower counts or performance guarantees are assumed.</p><button class=\"output-file\" data-artifact=\"creators\"><svg width=\"24\" height=\"28\" viewBox=\"0 0 24 28\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\"><path d=\"M4 1h10l6 6v20H4zM14 1v7h6M8 14h8M8 19h6\"/></svg><span><strong>Velora \u2014 creator shortlist.csv</strong><small>4 sample creator profiles \u00b7 Fit and verification checklist</small></span><span class=\"file-open\">Open</span></button>", "apps": ["X", "YouTube", "Project files"], "title": "Qualify the shortlist", "duration": 26, "key": "2-1"}, {"agent": "Claude", "prompt": "Use that shortlist and our market brief to plan a small creator pilot. Draft a specific message for the first two people, define the deliverable and success criteria, and save it for my review.", "status": ["Reading the shortlist and market brief", "Drafting two personal invitations and the pilot plan"], "output": "<h3>Lead with a real creative task, not a generic sponsorship.</h3><p><strong>Pilot:</strong> invite two creators to turn one supplied product image into three short ad variations. Ask for one honest workflow demo each, with a tracked link and space to discuss limitations.</p><p><strong>For Maya:</strong> \u201cYour product-to-video breakdowns are exactly the kind of workflow we\u2019re building for. Would you try turning one product photo into three ad directions in Velora, and show what holds up\u2014and what doesn\u2019t?\u201d</p><p><strong>For Prompt to Picture:</strong> \u201cWould you be interested in a brief-to-variations tutorial? We\u2019d provide a real product asset and early access; you\u2019d keep editorial control over the result.\u201d</p><p><strong>Measure:</strong> qualified visits \u2192 first generation \u2192 a second creation session. Agree compensation, usage rights and disclosure before the pilot.</p><button class=\"output-file\" data-artifact=\"outreach\"><svg width=\"24\" height=\"28\" viewBox=\"0 0 24 28\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\"><path d=\"M4 1h10l6 6v20H4zM14 1v7h6M8 14h8M8 19h6\"/></svg><span><strong>Velora \u2014 creator pilot & outreach.html</strong><small>2 personal drafts \u00b7 Deliverables and measurement</small></span><span class=\"file-open\">Open</span></button><p>Saved as drafts. Nothing has been sent.</p>", "apps": ["Creator shortlist", "Market PDF"], "title": "Prepare personal outreach", "duration": 26, "key": "2-2"}]}],workflowArtifacts={"report": {"name": "Velora \u2014 Market & product brief.pdf", "url": "data:application/pdf;base64,"}, "app": {"name": "Velora Studio \u2014 interactive prototype.html", "url": "data:text/html;base64,"}, "design": {"name": "Velora workspace \u2014 design preview.html", "url": "data:text/html;base64,"}, "creators": {"name": "Velora \u2014 creator shortlist.csv", "url": "data:text/csv;base64,"}, "outreach": {"name": "Velora \u2014 creator pilot & outreach.html", "url": "data:text/html;base64,"}};
let workflowCase=0,workflowTime=0,workflowPlaying=!matchMedia('(prefers-reduced-motion: reduce)').matches&&innerWidth>640,workflowVisible=false,workflowReady=false,workflowLast=0,workflowPaint=0;
const wf=document.querySelector('#workflow-frame'),wp=document.querySelector('#workflow-player'),wd=document.querySelector('#workflow-dialog');
let interactionMode=false,playingBeforeExplore=false;
wf.inert=true;
const totalTime=()=>[0,11,13][workflowCase]+workflowCases[workflowCase].steps.reduce((a,s)=>a+s.duration,0);
const fmt=s=>Math.floor(s/60)+':'+String(Math.floor(s%60)).padStart(2,'0');
function workflowResize(){wp.querySelector('.client-scale').style.transform='none'}
new ResizeObserver(workflowResize).observe(wp);
function workflowRender(){let state=null;if(workflowReady&&wf.contentWindow.renderDemo)state=wf.contentWindow.renderDemo(workflowCase,workflowTime);const index=state?.index??0,s=workflowCases[workflowCase].steps[index];document.querySelector('#workflow-current').innerHTML=escapeHTML(state?.agent||s.agent)+'<span>'+escapeHTML(state?.phase||'Getting started')+'</span>';document.querySelector('#workflow-apps').textContent=s.apps.join(' · ');document.querySelector('#workflow-play').innerHTML=icon(workflowPlaying?'pause':'play');document.querySelector('#workflow-play').setAttribute('aria-label',workflowPlaying?'Pause demo':workflowTime>=totalTime()?'Replay demo':'Play demo');document.querySelectorAll('[data-chapter]').forEach(b=>{if(+b.dataset.chapter===index)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current')});}
function workflowSelect(i){if(interactionMode)setInteraction(false,false);workflowCase=i;workflowTime=0;document.querySelectorAll('[data-workflow]').forEach((b,j)=>{b.setAttribute('aria-selected',String(i===j));b.tabIndex=i===j?0:-1});wp.setAttribute('aria-labelledby','workflow-tab-'+i);workflowRender()}
function downloadArtifact(id){const a=workflowArtifacts[id];if(!a)return;const raw=atob(a.url.split(',')[1]),bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);const blob=new Blob([bytes],{type:a.url.slice(5,a.url.indexOf(';'))}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=a.name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
window.addEventListener('message',e=>{if(e.source!==wf.contentWindow)return;if(e.data?.type==='minaco-demo-ready'){workflowReady=true;workflowRender();workflowResize()}if(e.data?.type==='minaco-download')downloadArtifact(e.data.id);if(e.data?.type==='minaco-demo-pause'&&interactionMode){workflowPlaying=false;workflowRender()}if(e.data?.type==='minaco-page-scroll'){const dy=Number(e.data.dy);if(Number.isFinite(dy)){if(wd.open)wd.scrollBy({top:dy,behavior:'instant'});else{if(interactionMode)setInteraction(false,false);window.scrollBy({top:dy,behavior:'instant'})}}}if(e.data?.type==='minaco-demo-escape'){if(wd.open)workflowClose();else setInteraction(false,true)}});
wf.addEventListener('load',()=>{wf.contentWindow.setDemoInteraction?.(interactionMode);workflowReady=!!wf.contentWindow.renderDemo;workflowRender();workflowResize()});
new IntersectionObserver(es=>{workflowVisible=es[0].isIntersecting;workflowLast=0},{threshold:.15}).observe(wp);
document.addEventListener('visibilitychange',()=>workflowLast=0);
function workflowTick(now){if(workflowLast&&workflowPlaying&&workflowReady&&(workflowVisible||wd.open)&&!document.hidden&&!document.querySelector('#home').hidden){workflowTime=Math.min(totalTime(),workflowTime+(now-workflowLast)/1000);if(workflowTime>=totalTime())workflowPlaying=false;if(now-workflowPaint>55||!workflowPlaying){workflowRender();workflowPaint=now}}workflowLast=now;requestAnimationFrame(workflowTick)}requestAnimationFrame(workflowTick);
document.querySelector('#workflow-play').onclick=()=>{if(interactionMode)setInteraction(false,false);wf.contentWindow.resumeDemo?.();if(workflowTime>=totalTime())workflowTime=0;workflowPlaying=!workflowPlaying;workflowRender()};


document.querySelectorAll('[data-workflow]').forEach(b=>{b.onclick=()=>{workflowPlaying=true;workflowSelect(+b.dataset.workflow)};b.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?2:(workflowCase+(e.key==='ArrowRight'?1:2))%3;workflowSelect(n);document.querySelector('[data-workflow="'+n+'"]').focus()}}});

document.querySelector('#workflow-expand').onclick=()=>{document.querySelector('#workflow-expanded').append(wp);wd.showModal();workflowResize()};
function workflowClose(){wd.close();setInteraction(false,true);document.querySelector('#player-home').append(wp);workflowResize();document.querySelector('#workflow-expand').focus()}
document.querySelector('#workflow-close').onclick=workflowClose;wd.addEventListener('cancel',e=>{e.preventDefault();workflowClose()});
matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',e=>{if(e.matches){workflowPlaying=false;workflowRender()}});
window.previewWorkflow=(i,time)=>{workflowPlaying=false;workflowSelect(i);workflowTime=time;workflowRender();return wf.contentWindow.demoState?.()};

function setInteraction(enabled,resume=false){
 if(enabled===interactionMode)return;
 if(enabled){playingBeforeExplore=workflowPlaying;workflowPlaying=false;interactionMode=true}else{interactionMode=false;if(resume&&playingBeforeExplore){wf.contentWindow.resumeDemo?.();workflowPlaying=true}}
 wf.inert=!interactionMode;
 wf.contentWindow.setDemoInteraction?.(interactionMode);
 const b=document.querySelector('#workflow-interact');b.textContent=interactionMode?'Back to page':'Explore demo';b.setAttribute('aria-pressed',String(interactionMode));
 wp.classList.toggle('is-exploring',interactionMode);workflowRender();
}
document.querySelector('#workflow-interact').onclick=()=>{if(interactionMode&&wd.open)workflowClose();else setInteraction(!interactionMode,true)};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&interactionMode&&!wd.open){e.preventDefault();setInteraction(false,true);document.querySelector('#workflow-interact').focus()}});
workflowSelect(0);




const publishedModelRates=window.minacoCatalog.models,publishedAgentNames=Object.fromEntries(window.minacoCatalog.agents.map(a=>[a.id,a.name]));
let modelRatePage=0;
function matchingModelRates(){const q=document.querySelector('#model-rate-search').value.trim().toLowerCase(),agent=document.querySelector('#model-rate-agent').value;return publishedModelRates.filter(m=>(agent==='all'||m.engines.includes(agent))&&(!q||[m.label,m.model,...m.engines.map(e=>publishedAgentNames[e]||e)].join(' ').toLowerCase().includes(q)))}
function renderModelRates(){const list=matchingModelRates(),size=document.querySelector('#model-rate-size').value==='all'?Math.max(1,list.length):8,pages=Math.max(1,Math.ceil(list.length/size));modelRatePage=Math.max(0,Math.min(modelRatePage,pages-1));const start=modelRatePage*size,visible=list.slice(start,start+size),num=n=>new Intl.NumberFormat('en-US',{maximumFractionDigits:3}).format(n),cacheWrite=m=>m.cacheWrite===undefined?'—':m.cacheWrite1h===undefined?num(m.cacheWrite):`${num(m.cacheWrite)} / ${num(m.cacheWrite1h)}`;document.querySelector('#model-rate-rows').innerHTML=visible.map(m=>`<tr><td><strong>${escapeHTML(m.label)}</strong><small>${escapeHTML(m.model)}</small>${m.pricingNote?`<small>${escapeHTML(m.pricingNote)}</small>`:''}</td><td>${m.engines.map(e=>escapeHTML(publishedAgentNames[e]||e)).join(', ')}</td><td>${num(m.input)}</td><td>${num(m.cachedInput)}</td><td>${cacheWrite(m)}</td><td>${num(m.output)}</td></tr>`).join('');document.querySelector('#model-rate-empty').hidden=list.length>0;document.querySelector('#model-rate-count').textContent=list.length?`${start+1}–${Math.min(start+size,list.length)} of ${list.length} model rates`:'0 model rates';document.querySelector('#model-rate-prev').disabled=modelRatePage===0;document.querySelector('#model-rate-next').disabled=modelRatePage>=pages-1}
for(const id of ['model-rate-search','model-rate-agent','model-rate-size'])document.getElementById(id).addEventListener(id==='model-rate-search'?'input':'change',()=>{modelRatePage=0;renderModelRates()});
document.querySelector('#model-rate-prev').onclick=()=>{modelRatePage--;renderModelRates()};document.querySelector('#model-rate-next').onclick=()=>{modelRatePage++;renderModelRates()};document.querySelector('#model-rate-reset').onclick=()=>{document.querySelector('#model-rate-search').value='';document.querySelector('#model-rate-agent').value='all';modelRatePage=0;renderModelRates();document.querySelector('#model-rate-search').focus()};
document.querySelector('#model-rate-download').onclick=()=>{const quote=x=>'"'+String(x).replaceAll('"','""')+'"',rows=[['Model','Model ID','Agent','Input credits per 1M tokens','Cached input credits per 1M tokens','5-minute cache write credits per 1M tokens','1-hour cache write credits per 1M tokens','Output credits per 1M tokens','Pricing note','Retrieved UTC'],...matchingModelRates().map(m=>[m.label,m.model,m.engines.map(e=>publishedAgentNames[e]||e).join(', '),m.input,m.cachedInput,m.cacheWrite??'',m.cacheWrite1h??'',m.output,m.pricingNote??'',window.minacoCatalog.generatedAt.slice(0,10)])],url=URL.createObjectURL(new Blob(['\ufeff'+rows.map(r=>r.map(quote).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='minaco-model-rates-'+window.minacoCatalog.generatedAt.slice(0,10)+'.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)};
renderModelRates();

const planCatalog=window.minacoCatalog.plans.filter(p=>p.key!=='FREE');
function drawPlans(cycle='monthly'){document.querySelector('#plans').innerHTML=planCatalog.map(p=>`<article class="plan ${p.highlighted?'featured':''}"><div class="plan-top"><h3>${escapeHTML(p.name)}</h3>${p.highlighted?'<span>For everyday work</span>':''}</div><p class="plan-intro">${escapeHTML(p.description)}</p><div class="price">$${cycle==='annual'?p.priceUsd*.8:p.priceUsd}<span> / month</span></div><p class="billing-line">${cycle==='annual'?'$'+Math.round(p.priceUsd*.8*12)+' billed yearly in USD':'Billed monthly in USD'}</p><div class="allowance"><strong>${(p.monthlyCredits*(cycle==='annual'?12:1)).toLocaleString('en-US')} credits / ${cycle==='annual'?'year':'month'}</strong><span>For AI usage included in your plan</span></div><ul><li>${icon('check')}${p.concurrentTasks} concurrent tasks</li><li>${icon('check')}${p.scheduledTasks} scheduled tasks</li><li>${icon('check')}${escapeHTML(p.modelTiers.join(' + '))} model access</li></ul><a class="btn ${p.highlighted?'primary':''}" href="/account?view=plan&amp;plan=${encodeURIComponent(p.key)}&amp;cycle=${cycle}">Choose ${escapeHTML(p.name)} ${icon('arrow')}</a></article>`).join('');document.querySelectorAll('[data-cycle]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.cycle===cycle)))}
document.querySelectorAll('[data-cycle]').forEach(b=>b.onclick=()=>drawPlans(b.dataset.cycle));drawPlans();
const agentSelect=document.querySelector('#model-rate-agent');agentSelect.innerHTML='<option value="all">All agents</option>'+[...new Set(publishedModelRates.flatMap(m=>m.engines))].sort().map(id=>'<option value="'+escapeHTML(id)+'">'+escapeHTML(publishedAgentNames[id]||id)+'</option>').join('');
if(!publishedModelRates.length){document.querySelector('#model-rate-empty strong').textContent='Model rates are temporarily unavailable.';document.querySelector('#model-rate-empty p').textContent='Please check back shortly.';document.querySelector('#model-rate-reset').hidden=true;document.querySelector('#model-rate-download').disabled=true}
const menu=document.querySelector('#mainnav'),menuButton=document.querySelector('#menubtn');menuButton.onclick=()=>{const opened=menu.classList.toggle('open');menuButton.setAttribute('aria-expanded',String(opened));menuButton.setAttribute('aria-label',opened?'Close navigation':'Open navigation')};menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{menu.classList.remove('open');menuButton.setAttribute('aria-expanded','false')}));document.addEventListener('keydown',e=>{if(e.key==='Escape'){menu.classList.remove('open');menuButton.setAttribute('aria-expanded','false')}});
